import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as n,o as r,ag as s,G as o}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"T3 Code source code walkthrough: how one sentence becomes one agent turn","description":"Read the T3 Code source against a pinned commit of pingdotgg/t3code: a repository map with measured size, the data flow of one thread from command, database write and agent start to the approval coming back to the interface, the few pieces of code that actually enforce the permission modes, the trust model of T3 Connect, and what packages/tailscale really uses Tailscale for.","frontmatter":{"title":"T3 Code source code walkthrough: how one sentence becomes one agent turn","description":"Read the T3 Code source against a pinned commit of pingdotgg/t3code: a repository map with measured size, the data flow of one thread from command, database write and agent start to the approval coming back to the interface, the few pieces of code that actually enforce the permission modes, the trust model of T3 Connect, and what packages/tailscale really uses Tailscale for.","domain":"product","tags":["coding-agent","source-code","agent-workspace"],"role":"deep-dive","pageClass":"wide-figures","source_revision":"d00aaac85fc71195f133a8580c3f0f2e29ac33a2"},"headers":[],"relativePath":"products/t3code/source.md","filePath":"products/t3code/source.md","lastUpdated":1795764761000}'),d={name:"products/t3code/source.md"};function h(l,e,c,p,k,g){const t=i("DocDiagram");return r(),n("div",null,[e[0]||(e[0]=s("",18)),o(t,{src:"/diagrams/t3code-architecture.en.svg",alt:"This layered architecture diagram answers one question: how do the desktop, web, and mobile interfaces drive separate external agent processes through the same server and the same adapter layer? It has four layers from top to bottom, and every arrow points one way. Layer 1 is the application layer: three clients, the desktop app, the web app, and the mobile app. They depend on only two shared packages: client-runtime, the connection and state layer shared by all three clients, and contracts, the typed wire contracts. All three reach the server over authenticated HTTP and WebSocket RPC. Layer 2 is the server, apps/server. It holds the Orchestrator, the EventSink that writes to the database, the EffectWorker that runs effects after commit, plus the terminal, Git, and checkpoints. The desktop app bundles a server, but its UI obeys the same boundary. The server reads only the capabilities an adapter declares and never the provider name. Layer 3 is the Provider adapters. The arrow goes from the server to the adapters and then from the adapters to layer 4, the external agent processes such as Claude Code, Codex, Cursor, and OpenCode. The adapters translate T3 Code operations into each agent's native protocol, and agent events are translated back along the same line; the external agent processes never depend back on the T3 Code interface. In its own column on the right is infra/relay, the T3 Connect relay. It has only a control relationship with the clients and the server, drawn as a dashed line: it helps with environment linking and credential issuing. Business traffic between the clients and the server never passes through it. This diagram leaves out the model itself, further modules inside the server, and optional external network paths such as Tailscale; T3 Code runs no model of its own.",width:960,lang:"en"}),e[1]||(e[1]=s("",66))])}const b=a(d,[["render",h]]);export{m as __pageData,b as default};
